  const takeLine = take != null && take > 0 ? isBitcoinSignal(t) ? `\u20BF \u0423\u0440\u043E\u0432\u0435\u043D\u044C \u0441\u043E\u043F\u0440\u043E\u0432\u043E\u0436\u0434\u0435\u043D\u0438\u044F +${take}% \u0434\u043E\u0441\u0442\u0438\u0433\u043D\u0443\u0442 (\u0447\u0430\u0441\u0442\u0438\u0447\u043D\u0430\u044F \u043F\u0440\u043E\u0434\u0430\u0436\u0430 \u043D\u0435 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u0430)` : `\u{1F3AF} \u0422\u0435\u0439\u043A: +${take}% \u0434\u043E\u0441\u0442\u0438\u0433\u043D\u0443\u0442` : isBitcoinSignal(t) ? `\u20BF \u0423\u0440\u043E\u0432\u0435\u043D\u044C \u0441\u043E\u043F\u0440\u043E\u0432\u043E\u0436\u0434\u0435\u043D\u0438\u044F \u043D\u0435 \u0434\u043E\u0441\u0442\u0438\u0433\u043D\u0443\u0442` : `\u{1F3AF} \u0422\u0435\u0439\u043A: \u043D\u0435 \u0434\u043E\u0441\u0442\u0438\u0433\u043D\u0443\u0442`;
