            candle_index, open, high, low, close, volume, vol_mult_24h,
            close_vs_level_pct, low_vs_level_pct, close_vs_trigger_close_pct,
            high_vs_trigger_close_pct, low_vs_trigger_close_pct,
            metrics, metrics_at
