async function discardUntrackedSignal(signalId, reason) {
  const deleted = await dbWriteBestEffort(
    "signals/discard-untracked",
    () => db.delete(signalsTable).where(
      sql`${signalsTable.id} = ${signalId}
            AND NOT EXISTS (
              SELECT 1 FROM tracked_signals ts
              WHERE ts.signal_id = ${signalsTable.id}
            )`
    ).returning({ id: signalsTable.id })
  ) ?? [];
  if (deleted.length > 0) {
    logger.info(
      { signalId, reason },
      "Preliminary signal discarded because no tracked position was created"
    );
  }
  return deleted.length > 0;
}
