async function sendNearStopWarning() {
  try {
    const openPositions = await db.select().from(trackedSignalsTable).where(inArray(trackedSignalsTable.status, ["active", "in_run"]));
    if (openPositions.length === 0) return;
    let tickers = [];
    try {
      tickers = await getFutureTickers();
    } catch {
      return;
    }
    const priceMap = /* @__PURE__ */ new Map();
    for (const t of tickers)
      priceMap.set(t.symbol, parseFloat(t.lastPrice) || 0);
    const nearStop = [];
    for (const pos of openPositions) {
      if (!pos.entryPrice || pos.entryPrice === 0) continue;
      const curPrice = priceMap.get(pos.symbol);
      if (!curPrice) continue;
      const pnl2 = computePnl(pos, curPrice);
      const isOpenRunner = isImpulseRunnerCoreClosed(pos) && pos.runnerState === "open";
      const runnerEntryPrice = pos.originalEntryPrice ?? pos.entryPrice;
      const stopPct = isOpenRunner ? (runnerEntryPrice - resolveImpulseRunnerEmergencyStopPrice(
        runnerEntryPrice,
        pos.stopLossPct,
        pos.entryPolicyVersion
      )) / runnerEntryPrice * 100 : effStopPct(pos);
      if (pnl2 < 0 && Math.abs(pnl2) >= stopPct * 0.5) {
        nearStop.push({
          symbol: pos.symbol,
          sentimentKey: pos.sentimentKey,
          pnl: pnl2,
          stopPct,
          remaining: stopPct - Math.abs(pnl2),
          currentPrice: curPrice,
          isOpenRunner
        });
      }
    }
    if (nearStop.length === 0) return;
    const lines = [
      `\u26A0\uFE0F <b>MANUAL CHECK \u2014 \u043F\u043E\u0437\u0438\u0446\u0438\u0438 \u0431\u043B\u0438\u0437\u043A\u043E \u043A \u0441\u0442\u043E\u043F\u0443</b>`,
      ``,
      ...nearStop.map((p) => {
        const base = p.symbol.replace("-USDT", "");
        const pattern = p.sentimentKey ? getPatternTgLabel(p.sentimentKey) : "\u043D\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u0435\u043D";
        return `\u2022 <b>${base}</b> ${tickerTag(p.symbol)} | <b>${pattern}</b> | PnL${p.isOpenRunner ? " runner" : ""}: <b>${p.pnl.toFixed(1)}%</b>
${formatMarketLinks(p.symbol)}`;
      })
    ];
    const text2 = withoutTradingViewLinks(lines.join("\n"));
    const targets = await getTargets({ strict: true });
    for (let attempt = 1; attempt <= 3; attempt++) {
      try {
        const delivery = await queueSettingsPhotoBroadcast({
          column: "lastManualCheckSentAt",
          windowMs: 10 * 6e4,
          eventKey: `manual-check:${Math.floor(Date.now() / (10 * 6e4))}`,
          photoPath: MANUAL_CHECK_IMG,
          text: text2,
          targets
        });
        if (!delivery.claimed) {
          logger.info(
            "Manual Check near-stop: already queued by another worker"
          );
          return;
        }
        if (delivery.queued > 0) {
          logger.warn(
            {
              nearStopCount: nearStop.length,
              symbols: nearStop.map((p) => p.symbol),
              queued: delivery.queued
            },
            "\u26A0\uFE0F Near-stop positions detected after restart \u2014 manual check queued for confirmed delivery"
          );
          return;
        }
        throw new Error("Manual Check claim succeeded without recipient rows");
      } catch (err) {
        if (attempt === 3) throw err;
        logger.warn(
          { err, attempt },
          "Manual Check near-stop: queue failed, retry in 15s"
        );
        await new Promise((resolve) => setTimeout(resolve, 15e3));
      }
    }
  } catch (err) {
    logger.error(
      { err },
      "sendNearStopWarning: unable to queue the critical manual check"
    );
  }
}
