    const action = r.verdict === "enter" ? "\u0412\u0425\u041E\u0414\u0418\u0422\u042C" : r.verdict === "wait" ? "\u0416\u0414\u0410\u0422\u042C" : "\u041F\u0420\u041E\u041F\u0423\u0421\u0422\u0418\u0422\u042C";
