// src/lib/scannerCycleAbort.ts
function createScannerCycleAbort() {
  const controller = new AbortController();
  let timeout = null;
  return {
    controller,
    signal: controller.signal,
    armHardTimeout(timeoutMs, onTimeout) {
      if (timeout) clearTimeout(timeout);
      timeout = setTimeout(() => {
        const error40 = new Error(
          "SCAN_HARD_TIMEOUT: scan exceeded its deadline and was cancelled"
        );
        controller.abort(error40);
        onTimeout(error40);
      }, timeoutMs);
    },
    dispose() {
      if (timeout) clearTimeout(timeout);
      timeout = null;
    }
  };
}

