          shortHistory: stats.shortHistory,
          failed: stats.failed,
          cancelled: stats.cancelled,
          queuedRemaining: stats.queuedRemaining,
          replayWindow: AUTO_RANGE_1H_REPLAY_WINDOW,
          ...autoRangeHistoryQueue.cacheStats(),
