// src/lib/stealth-window-calibration.ts
var STEALTH_WINDOW_VERSION = "stealth-30m-hold-v1";
var STEALTH_WINDOW_MIN_COMPLETED = 20;
function round3(value) {
  return value == null ? null : Number(value.toFixed(2));
}
function replayStealthWindowStop(row, stopPct) {
  const horizonEnd = Math.min(row.closedAt, row.entryAt + 72 * 60 * 60 * 1e3);
  const candles = row.candles.filter(
    (candle) => Number.isFinite(candle.time) && candle.time >= row.entryAt && candle.time <= horizonEnd
  ).sort((left, right) => left.time - right.time);
  const entry = row.entryPrice;
  if (!(entry > 0) || candles.length === 0) {
    return { hit: false, hitAt: null, mfePct: null, maePct: null };
  }
  let mfe = -Infinity;
  let mae = Infinity;
  const stop = entry * (1 - stopPct / 100);
  for (const candle of candles) {
    mfe = Math.max(mfe, (candle.high / entry - 1) * 100);
    mae = Math.min(mae, (candle.low / entry - 1) * 100);
    if (candle.low <= stop) {
      return {
        hit: true,
        hitAt: candle.time,
        mfePct: round3(mfe),
        maePct: round3(mae)
      };
    }
  }
  return {
    hit: false,
    hitAt: null,
    mfePct: round3(mfe === -Infinity ? null : mfe),
    maePct: round3(mae === Infinity ? null : mae)
  };
}
function analyzeStealthWindowCalibration(rows) {
  const ordered = [...rows].sort((left, right) => left.entryAt - right.entryAt);
  const outcomes = { profit: 0, bu: 0, breakeven: 0, stop: 0, expired: 0 };
  let pnl2 = 0;
  let pnlCount = 0;
  let mfe = 0;
  let mae = 0;
  let metricRows = 0;
  const stops = [6, 8, 10].map((stopPct) => {
    let favorableActualTurnedIntoStops = 0;
    let eventualActualStopsImproved = 0;
    let candidateStops = 0;
    for (const row of ordered) {
      const replay = replayStealthWindowStop(row, stopPct);
      if (replay.hit) candidateStops++;
      if ((row.outcome === "profit" || row.outcome === "bu_stop" || row.outcome === "breakeven") && replay.hit) {
        favorableActualTurnedIntoStops++;
      }
      if (row.outcome === "stop_loss" && replay.hit)
        eventualActualStopsImproved++;
    }
    return {
      stopPct,
      favorableActualTurnedIntoStops,
      eventualActualStopsImproved,
      candidateStops
    };
  });
  for (const row of ordered) {
    const key = row.outcome === "bu_stop" ? "bu" : row.outcome === "stop_loss" ? "stop" : row.outcome;
    outcomes[key]++;
    const pathEnd = Math.min(row.closedAt, row.entryAt + 72 * 60 * 60 * 1e3);
    const path = row.candles.filter(
      (candle) => candle.time >= row.entryAt && candle.time <= pathEnd
    );
    const replay = replayStealthWindowStop(row, 10);
    if (row.pnlPct != null && Number.isFinite(row.pnlPct)) {
      pnl2 += row.pnlPct;
      pnlCount++;
    }
    const pathMfe = path.length > 0 ? Math.max(
      ...path.map((candle) => (candle.high / row.entryPrice - 1) * 100)
    ) : null;
    const pathMae = path.length > 0 ? Math.min(
      ...path.map((candle) => (candle.low / row.entryPrice - 1) * 100)
    ) : null;
    if (pathMfe != null && pathMae != null && replay) {
      mfe += pathMfe;
      mae += pathMae;
      metricRows++;
    }
  }
  const durationDays = ordered.length > 1 ? (ordered[ordered.length - 1].entryAt - ordered[0].entryAt) / 864e5 : null;
  return {
    decision: ordered.length < STEALTH_WINDOW_MIN_COMPLETED ? "insufficient_cohort" : "ready_for_decision",
    version: STEALTH_WINDOW_VERSION,
    minimumCompleted: STEALTH_WINDOW_MIN_COMPLETED,
    completed: ordered.length,
    signalFrequency: {
      total: ordered.length,
      perDay: durationDays && durationDays > 0 ? round3(ordered.length / durationDays) : null
    },
    outcomes,
    avgPnlPct: pnlCount > 0 ? round3(pnl2 / pnlCount) : null,
    avgMfePct: metricRows > 0 ? round3(mfe / metricRows) : null,
    avgMaePct: metricRows > 0 ? round3(mae / metricRows) : null,
    stops
  };
}

