      watchId: row.watch_id,
      symbol: row.symbol,
      detectedAt: asDate(row.detected_at).toISOString(),
      status: row.status,
      wickState: row.wick_state,
      watchReason: row.watch_reason,
      liquidationUsd1h: numberOrNull2(snapshot.longLiq1hAtDetect),
      liquidationUsd24h: numberOrNull2(snapshot.longLiq24hAtDetect),
      wickConfirmedAt: row.wick_confirmed_at === null ? null : asDate(row.wick_confirmed_at).toISOString(),
      wickLow: row.wick_low,
      wickClose: row.wick_close,
      volumeMultiple: row.volume_multiple,
      forward120mReturnPct: outcome?.status === "complete" ? numberOrNull2(outcome.closeReturnPct) : null,
      forward120mMaxPct: outcome?.status === "complete" ? numberOrNull2(outcome.maxPct) : null,
      forward120mMinPct: outcome?.status === "complete" ? numberOrNull2(outcome.minPct) : null,
      source: row.snapshot_source
