router6.get(
  "/admin/tracker/indicator-target-observations",
  requireAdminToken,
  async (req, res) => {
    const parsedQuery = GetAdminTrackerIndicatorTargetObservationsQueryParams.safeParse(
      req.query
    );
    if (!parsedQuery.success) {
      res.status(400).json({ error: parsedQuery.error.message });
      return;
    }
    try {
      const [experiment] = await db.select({
        startAt: indicatorTargetObservationExperimentsTable.startAt
      }).from(indicatorTargetObservationExperimentsTable).where(
        eq(
          indicatorTargetObservationExperimentsTable.experimentVersion,
          INDICATOR_TARGET_OBSERVATION_VERSION
        )
      ).limit(1);
      if (!experiment) {
        req.log.error(
          { experimentVersion: INDICATOR_TARGET_OBSERVATION_VERSION },
          "Indicator target experiment start is missing"
        );
        res.status(503).json({ error: "Indicator target experiment unavailable" });
        return;
      }
      const complete72h = sql`
        ${indicatorTargetObservationsTable.followupStatus} = 'complete'
        AND ${indicatorTargetObservationsTable.followupSampleCount} = 288
        AND ${indicatorTargetObservationsTable.followupExpectedSampleCount} = 288
        AND ${indicatorTargetObservationsTable.priceAt72h} IS NOT NULL
        AND ${indicatorTargetObservationsTable.priceAt72hObservedAt}
          = ${indicatorTargetObservationsTable.followupDeadline}
      `;
      const versionCondition = eq(
        indicatorTargetObservationsTable.experimentVersion,
        INDICATOR_TARGET_OBSERVATION_VERSION
      );
      const eligibleTrackerCondition = and(
        eq(trackedSignalsTable.isShort, false),
        isNotNull(trackedSignalsTable.signalId),
        gt(trackedSignalsTable.entryPrice, 0),
        gte(trackedSignalsTable.detectedAt, experiment.startAt)
      );
      const [
        eligible,
        enrolled,
        durableProgress,
        groups,
        provenanceRows,
        recent
      ] = await Promise.all([
        db.select({
          trackedSignals: sql`count(DISTINCT ${trackedSignalsTable.id})::int`
        }).from(trackedSignalsTable).where(eligibleTrackerCondition),
        db.select({
          trackedSignals: sql`count(*)::int`
        }).from(trackedSignalsTable).where(
          and(
            eligibleTrackerCondition,
            sql`(
                  SELECT count(DISTINCT observation.target_pct)
                  FROM indicator_target_observations observation
                  WHERE observation.tracked_signal_id = ${trackedSignalsTable.id}
                    AND observation.experiment_version = ${INDICATOR_TARGET_OBSERVATION_VERSION}
                    AND observation.target_pct IN (8, 12, 16)
                ) = 3`
          )
        ),
        db.select({
          observationRows: sql`count(*)::int`,
          attempts: sql`coalesce(sum(${indicatorTargetObservationsTable.attempts}), 0)::int`,
          lastUpdatedAt: sql`max(${indicatorTargetObservationsTable.updatedAt})`
        }).from(indicatorTargetObservationsTable).where(versionCondition),
        db.select({
          pattern: indicatorTargetObservationsTable.pattern,
          targetPct: indicatorTargetObservationsTable.targetPct,
          total: sql`count(*)::int`,
          awaitingHit: sql`count(*) FILTER (WHERE ${indicatorTargetObservationsTable.status} = 'awaiting_hit')::int`,
          hit: sql`count(*) FILTER (WHERE ${indicatorTargetObservationsTable.status} = 'hit')::int`,
          noHitBeforeClose: sql`count(*) FILTER (WHERE ${indicatorTargetObservationsTable.status} = 'no_hit_before_close')::int`,
          unknown: sql`count(*) FILTER (WHERE ${indicatorTargetObservationsTable.status} = 'unknown')::int`,
          followupNotStarted: sql`count(*) FILTER (WHERE ${indicatorTargetObservationsTable.followupStatus} = 'not_started')::int`,
          followupPending: sql`count(*) FILTER (WHERE ${indicatorTargetObservationsTable.followupStatus} = 'pending')::int`,
          followupDelayed: sql`count(*) FILTER (WHERE ${indicatorTargetObservationsTable.followupStatus} = 'delayed')::int`,
          followupRetry: sql`count(*) FILTER (WHERE ${indicatorTargetObservationsTable.followupStatus} = 'retry')::int`,
          followupComplete: sql`count(*) FILTER (WHERE ${complete72h})::int`,
          followupPartial: sql`count(*) FILTER (WHERE ${indicatorTargetObservationsTable.followupStatus} = 'partial')::int`,
          followupUnavailable: sql`count(*) FILTER (WHERE ${indicatorTargetObservationsTable.followupStatus} = 'unavailable')::int`,
          followupNotApplicable: sql`count(*) FILTER (WHERE ${indicatorTargetObservationsTable.followupStatus} = 'not_applicable')::int`,
          completeOutcomeCount: sql`count(*) FILTER (WHERE ${complete72h})::int`,
          completeAverageChangePct: sql`avg(${indicatorTargetObservationsTable.priceAt72hChangePct}) FILTER (WHERE ${complete72h})`,
          completePositiveAfter72: sql`count(*) FILTER (WHERE ${complete72h} AND ${indicatorTargetObservationsTable.priceAt72hChangePct} > 0)::int`,
          completeAverageMaxFavorablePct: sql`avg(${indicatorTargetObservationsTable.maxFavorablePct}) FILTER (WHERE ${complete72h})`,
          completeAverageMinFavorablePct: sql`avg(${indicatorTargetObservationsTable.minFavorablePct}) FILTER (WHERE ${complete72h})`
        }).from(indicatorTargetObservationsTable).where(versionCondition).groupBy(
          indicatorTargetObservationsTable.pattern,
          indicatorTargetObservationsTable.targetPct
        ).orderBy(
          asc(indicatorTargetObservationsTable.pattern),
          asc(indicatorTargetObservationsTable.targetPct)
        ),
        db.select({
          status: indicatorTargetObservationsTable.indicatorProvenanceStatus,
          trackedSignals: sql`count(DISTINCT ${indicatorTargetObservationsTable.trackedSignalId})::int`
        }).from(indicatorTargetObservationsTable).where(versionCondition).groupBy(indicatorTargetObservationsTable.indicatorProvenanceStatus).orderBy(
          asc(indicatorTargetObservationsTable.indicatorProvenanceStatus)
        ),
        db.select({
          trackedSignalId: indicatorTargetObservationsTable.trackedSignalId,
          symbol: indicatorTargetObservationsTable.symbol,
          pattern: indicatorTargetObservationsTable.pattern,
          signalAt: indicatorTargetObservationsTable.signalAt,
          targetPct: indicatorTargetObservationsTable.targetPct,
          indicatorProvenanceStatus: indicatorTargetObservationsTable.indicatorProvenanceStatus,
          status: indicatorTargetObservationsTable.status,
          hitAt: indicatorTargetObservationsTable.hitAt,
          hitPrice: indicatorTargetObservationsTable.hitPrice,
          hitSource: indicatorTargetObservationsTable.hitSource,
          tradeClosedAt: indicatorTargetObservationsTable.tradeClosedAt,
          followupStatus: indicatorTargetObservationsTable.followupStatus,
          followupDeadline: indicatorTargetObservationsTable.followupDeadline,
          priceAt72h: indicatorTargetObservationsTable.priceAt72h,
          priceAt72hChangePct: indicatorTargetObservationsTable.priceAt72hChangePct,
          maxFavorablePct: indicatorTargetObservationsTable.maxFavorablePct,
          minFavorablePct: indicatorTargetObservationsTable.minFavorablePct,
          followupSampleCount: indicatorTargetObservationsTable.followupSampleCount,
          followupExpectedSampleCount: indicatorTargetObservationsTable.followupExpectedSampleCount,
          priceAt72hObservedAt: indicatorTargetObservationsTable.priceAt72hObservedAt
        }).from(indicatorTargetObservationsTable).where(versionCondition).orderBy(
          desc(indicatorTargetObservationsTable.signalAt),
          desc(indicatorTargetObservationsTable.id)
        ).limit(parsedQuery.data.limit)
      ]);
      const workerHealth2 = getIndicatorTargetObservationWorkerHealth();
      const shaped = buildIndicatorTargetObservationsResponse(groups, recent);
      res.json(
        GetAdminTrackerIndicatorTargetObservationsResponse.parse({
          ...shaped,
          experimentVersion: INDICATOR_TARGET_OBSERVATION_VERSION,
          experimentStartedAt: observationDate(experiment.startAt),
          eligibleTrackedSignalsSinceStart: observationNumber(
            eligible[0]?.trackedSignals
          ),
          enrolledTrackedSignalsSinceStart: observationNumber(
            enrolled[0]?.trackedSignals
          ),
          missingEnrollmentTrackedSignalsSinceStart: Math.max(
            0,
            observationNumber(eligible[0]?.trackedSignals) - observationNumber(enrolled[0]?.trackedSignals)
          ),
          durableProgress: {
            observationRows: observationNumber(
              durableProgress[0]?.observationRows
            ),
            attempts: observationNumber(durableProgress[0]?.attempts),
            lastUpdatedAt: observationDate(durableProgress[0]?.lastUpdatedAt)
          },
          workerProcess: {
            lastAttemptAt: observationDate(workerHealth2.lastAttemptAt),
            lastSuccessAt: observationDate(workerHealth2.lastSuccessAt),
            lastErrorAt: observationDate(workerHealth2.lastErrorAt),
            lastError: workerHealth2.lastError ?? null,
            lastEnrolled: observationNumber(workerHealth2.lastEnrolled),
            lastProcessed: observationNumber(workerHealth2.lastProcessed)
          },
          indicatorProvenanceCoverage: provenanceRows.map((row) => ({
            status: row.status,
            trackedSignals: observationNumber(row.trackedSignals)
          })),
          decisionUse: false,
          takeProfitRecommendation: false
        })
      );
    } catch (err) {
      req.log.error({ err }, "Indicator target observation report failed");
      res.status(503).json({ error: "Indicator target observation report unavailable" });
    }
  }
);
