router6.get("/tracker/stats", async (req, res) => {
  try {
    const monthStart = getDubaiMonthStart();
    const [rows, monthRows, monthBuStopMilestoneRows, monthAvgPeakRows] = await Promise.all([
      db.select({
        status: trackedSignalsTable.status,
        count: sql`count(*)::int`,
        avgPnl: sql`round(avg(${normalizedTrackedPnlSql()})::numeric, 2)`,
        positiveCount: sql`count(*) filter (where ${normalizedTrackedPnlSql()} > 0)::int`,
        negativeCount: sql`count(*) filter (where ${normalizedTrackedPnlSql()} < 0)::int`,
        breakevenCount: sql`count(*) filter (where ${normalizedTrackedPnlSql()} = 0)::int`
      }).from(trackedSignalsTable).where(
        and(
          activeTrackedPatternCondition(),
          ne(trackedSignalsTable.status, "reclassified"),
          currentStatsCohortCondition()
        )
      ).groupBy(trackedSignalsTable.status),
      db.select({
        status: trackedSignalsTable.status,
        count: sql`count(*)::int`,
        avgPnl: sql`round(avg(${normalizedTrackedPnlSql()})::numeric, 2)`,
        pnlSum: sql`coalesce(sum(${normalizedTrackedPnlSql()}), 0)`,
        positiveCount: sql`count(*) filter (where ${normalizedTrackedPnlSql()} > 0)::int`,
        negativeCount: sql`count(*) filter (where ${normalizedTrackedPnlSql()} < 0)::int`,
        breakevenCount: sql`count(*) filter (where ${normalizedTrackedPnlSql()} = 0)::int`,
        positivePnlSum: sql`coalesce(sum(${normalizedTrackedPnlSql()}) filter (where ${normalizedTrackedPnlSql()} > 0), 0)`,
        negativePnlSum: sql`coalesce(sum(${normalizedTrackedPnlSql()}) filter (where ${normalizedTrackedPnlSql()} < 0), 0)`
      }).from(trackedSignalsTable).where(
        and(
          // Owner 2026-10-24: profitable trades of retired PLM stay in the
          // current-month counter; its other outcomes remain outside it.
          or(
            activeTrackedPatternCondition(),
            and(
              eq(trackedSignalsTable.sentimentKey, "price_led_momentum"),
              eq(trackedSignalsTable.status, "profit")
            )
          ),
          ne(trackedSignalsTable.status, "reclassified"),
          currentStatsCohortCondition(),
          or(
            and(
              inArray(trackedSignalsTable.status, [...OPEN_STATUSES]),
              gte(trackedSignalsTable.detectedAt, monthStart)
            ),
            and(
              not(inArray(trackedSignalsTable.status, [...OPEN_STATUSES])),
              isNotNull(trackedSignalsTable.closedAt),
              gte(trackedSignalsTable.closedAt, monthStart)
            )
          )
        )
      ).groupBy(trackedSignalsTable.status),
      db.select({
        bucket: buStopMilestoneBucketSql(),
        count: sql`count(*)::int`
      }).from(trackedSignalsTable).where(
        and(
          eq(trackedSignalsTable.status, "bu_stop"),
          activeTrackedPatternCondition(),
          isNotNull(trackedSignalsTable.closedAt),
          gte(trackedSignalsTable.closedAt, monthStart)
        )
      ).groupBy(buStopMilestoneBucketSql()),
      db.select({
        avgPeak: sql`round(avg((peak_price - CASE WHEN policy_version = 'impulse_runner_v1' THEN original_entry_price ELSE entry_price END) / nullif(CASE WHEN policy_version = 'impulse_runner_v1' THEN original_entry_price ELSE entry_price END, 0) * 100)::numeric, 2)`
      }).from(trackedSignalsTable).where(
        and(
          activeTrackedPatternCondition(),
          inArray(trackedSignalsTable.status, ["profit", "stop_loss"]),
          currentStatsCohortCondition(),
          isNotNull(trackedSignalsTable.closedAt),
          gte(trackedSignalsTable.closedAt, monthStart)
        )
      )
    ]);
    const stats = {};
    for (const row of rows)
      stats[row.status] = {
        count: row.count,
        avgPnl: row.avgPnl,
        positiveCount: Number(row.positiveCount ?? 0),
        negativeCount: Number(row.negativeCount ?? 0),
        breakevenCount: Number(row.breakevenCount ?? 0)
      };
    const monthStats = {};
    for (const row of monthRows)
      monthStats[row.status] = {
        count: row.count,
        avgPnl: row.avgPnl,
        pnlSum: Number(row.pnlSum ?? 0),
        positiveCount: Number(row.positiveCount ?? 0),
        negativeCount: Number(row.negativeCount ?? 0),
        breakevenCount: Number(row.breakevenCount ?? 0),
        positivePnlSum: Number(row.positivePnlSum ?? 0),
        negativePnlSum: Number(row.negativePnlSum ?? 0)
      };
    const monthBuStopMilestones = toBuStopMilestoneCounts(
      monthBuStopMilestoneRows
    );
    const total = rows.reduce((s, r) => s + r.count, 0);
    const allTimeProfit = stats["profit"]?.count ?? 0;
    const allTimeBuStop = stats["bu_stop"]?.count ?? 0;
    const allTimeStopLoss = stats["stop_loss"]?.count ?? 0;
    const allTimeWinRateDenominator = allTimeProfit + allTimeBuStop + allTimeStopLoss;
    const winRate2 = allTimeWinRateDenominator > 0 ? Math.round(
      (allTimeProfit + allTimeBuStop) / allTimeWinRateDenominator * 100
    ) : null;
    const avgProfit = stats["profit"]?.avgPnl != null ? Number(stats["profit"].avgPnl) : null;
    const avgLoss = stats["stop_loss"]?.avgPnl != null ? Number(stats["stop_loss"].avgPnl) : null;
    const rawPnlStatuses = [
      "profit",
      "stop_loss",
      "expired",
      "cancelled"
    ];
    const monthNonCancelledPositiveCount = NON_CANCELLED_PNL_STATUSES.reduce(
      (sum2, status) => sum2 + (monthStats[status]?.positiveCount ?? 0),
      0
    );
    const monthNonCancelledNegativeCount = NON_CANCELLED_PNL_STATUSES.reduce(
      (sum2, status) => sum2 + (monthStats[status]?.negativeCount ?? 0),
      0
    );
    const monthNonCancelledPositivePnlSum = NON_CANCELLED_PNL_STATUSES.reduce(
      (sum2, status) => sum2 + (monthStats[status]?.positivePnlSum ?? 0),
      0
    );
    const monthNonCancelledNegativePnlSum = NON_CANCELLED_PNL_STATUSES.reduce(
      (sum2, status) => sum2 + (monthStats[status]?.negativePnlSum ?? 0),
      0
    );
    const monthProfit = monthStats["profit"]?.count ?? 0;
    const monthBuStop = monthStats["bu_stop"]?.count ?? 0;
    const monthStopLoss = monthStats["stop_loss"]?.count ?? 0;
    const monthWinRateDenominator = monthProfit + monthBuStop + monthStopLoss;
    const monthWinRate = monthWinRateDenominator > 0 ? Math.round(
      (monthProfit + monthBuStop) / monthWinRateDenominator * 100
    ) : null;
    const monthAvgProfit = monthNonCancelledPositiveCount > 0 ? monthNonCancelledPositivePnlSum / monthNonCancelledPositiveCount : null;
    const monthAvgLoss = monthNonCancelledNegativeCount > 0 ? monthNonCancelledNegativePnlSum / monthNonCancelledNegativeCount : null;
    const monthAvgPeak = monthAvgPeakRows[0]?.avgPeak != null ? Number(monthAvgPeakRows[0].avgPeak) : null;
    const monthNetPnlPercent = Math.round(
      rawPnlStatuses.reduce(
        (sum2, status) => sum2 + (monthStats[status]?.pnlSum ?? 0),
        0
      ) * 100
    ) / 100;
    res.json({
      stats,
      total,
      winRate: winRate2,
      avgProfit,
      avgLoss,
      monthStats,
      monthWinRate,
      monthAvgProfit,
      monthAvgLoss,
      monthAvgPeak,
      monthNetPnlPercent,
      monthBuStopAfter5: monthBuStopMilestones.after5,
      monthBuStopAfter8: monthBuStopMilestones.after8,
      monthBuStopAfter10: monthBuStopMilestones.after10
    });
  } catch (_err) {
    res.status(500).json({ error: "Failed to fetch tracker stats" });
  }
});
