router6.post("/admin/resend-milestone", requireAdminToken, async (req, res) => {
  const { symbol: symbol2, milestone } = req.body;
  if (!symbol2 || !milestone) {
    res.status(400).json({ error: "symbol and milestone required" });
    return;
  }
  try {
    const rows = await db.select().from(trackedSignalsTable).where(
      and(
        eq(trackedSignalsTable.symbol, symbol2.toUpperCase()),
        inArray(trackedSignalsTable.status, ["in_run", "active"])
      )
    ).limit(1);
    if (rows.length === 0) {
      res.status(404).json({ error: `No active/in_run signal found for ${symbol2}` });
      return;
    }
    const tracked = rows[0];
    const MILESTONE_IMGS = {
      10: new URL("../../assets/milestone10.png", import.meta.url).pathname,
      15: new URL("../../assets/milestone15.png", import.meta.url).pathname,
      25: new URL("../../assets/moonshot.png", import.meta.url).pathname,
      50: new URL("../../assets/milestone50.png", import.meta.url).pathname,
      100: new URL("../../assets/milestone100.png", import.meta.url).pathname
    };
    const imgPath = tracked.symbol === "BTC-USDT" || tracked.symbol === "BTCUSDT" || milestone > 200 ? new URL("../../assets/target_hit.png", import.meta.url).pathname : MILESTONE_IMGS[milestone];
    const currentPrice = tracked.exitPrice ?? tracked.peakPrice ?? tracked.entryPrice;
    const trailingStop = resolveTrailingStopLevel({
      entryPrice: tracked.entryPrice,
      peakPrice: tracked.peakPrice ?? currentPrice,
      trailingGapPercent: getExitProfile(tracked.sentimentKey, tracked.symbol).trailingGap,
      persistedTrailingStopLevel: tracked.trailingStopLevel
    });
    const text2 = msgMilestone(tracked, milestone, currentPrice, trailingStop);
    if (imgPath) {
      await broadcastPhoto(imgPath, text2);
    } else {
      await adminBroadcast(text2);
    }
    req.log.info({ symbol: symbol2, milestone }, "admin/resend-milestone sent");
    res.json({ ok: true, symbol: symbol2, milestone, withPhoto: !!imgPath });
  } catch (err) {
    req.log.error({ err }, "admin/resend-milestone error");
    res.status(500).json({ error: String(err) });
  }
});
