        pnlPercent: r.policyVersion === "impulse_runner_v1" && r.runnerState === "open" ? null : normalizeClosedPnlPercent(r.status, r.pnlPercent, r.sentimentKey),
        pnlDisplayMode: r.policyVersion === "impulse_runner_v1" && r.runnerState === "open" ? "runner_live_required" : "final",
        // Canonical final PnL is the pure runner return from original entry.
