// src/lib/stealth-open-breakout-volume-backfill.ts
init_src();
init_drizzle_orm();
init_bingx();
init_logger2();
var HOUR_MS9 = 60 * 60 * 1e3;
var LOOKBACK3 = 20;
async function backfillOpenStealthBreakoutVolume() {
  if (process.env.NODE_ENV !== "production") return 0;
  const result = await db.execute(sql`
    SELECT t.id, t.symbol,
           (a.decision_json->'confirmation'->>'triggerCandleAt')::bigint AS trigger_at
      FROM tracked_signals t
      JOIN stealth_breakout_armed_setups a ON a.fired_signal_id = t.signal_id
     WHERE t.sentiment_key = 'stealth_breakout'
       AND t.status::text IN ('active', 'in_run')
       AND a.level_source = 'auto_range_1h'
       AND a.decision_json->'confirmation'->>'triggerCandleAt' IS NOT NULL
       AND NOT (COALESCE(t.decision_metrics, '{}'::jsonb) ? 'entryVolume')
       AND NOT (COALESCE(t.decision_metrics, '{}'::jsonb) ? 'breakoutVolumeBackfill')
  `);
  let written = 0;
  for (const row of result.rows) {
    try {
      const triggerAt = Number(row.trigger_at);
      const candles = await withAggregatedKlineVolume(
        row.symbol,
        "1h",
        await getKlinesRange(
          row.symbol,
          "1h",
          triggerAt - (LOOKBACK3 + 1) * HOUR_MS9,
          triggerAt + HOUR_MS9,
          { strictPayload: true }
        )
      );
      const bar = candles.find((c) => Number(c.time) === triggerAt);
      const prior = candles.filter(
        (c) => Number(c.time) < triggerAt && Number(c.time) >= triggerAt - LOOKBACK3 * HOUR_MS9
      );
      if (!bar || prior.length !== LOOKBACK3) {
        logger.warn(
          { id: row.id, symbol: row.symbol },
          "Stealth breakout volume backfill skipped: candles incomplete"
        );
        continue;
      }
      const volume = Number(bar.volume);
      const close = Number(bar.close);
      const priorMean = prior.reduce((s, c) => s + Number(c.volume), 0) / LOOKBACK3;
      if (!(volume > 0) || !(priorMean > 0) || !Number.isFinite(close))
        continue;
      const payload = {
        source: "backfilled_from_closed_1h_klines",
        timeframe: "1h",
        breakoutCandleTime: triggerAt,
        volume,
        turnoverUsd: volume * close,
        priorMeanVolume: priorMean,
        ratio: volume / priorMean,
        backfilledAt: Date.now()
      };
      await db.execute(sql`
        UPDATE tracked_signals
           SET decision_metrics = COALESCE(decision_metrics, '{}'::jsonb) ||
               jsonb_build_object('breakoutVolumeBackfill', ${JSON.stringify(payload)}::jsonb)
         WHERE id = ${row.id}
           AND NOT (COALESCE(decision_metrics, '{}'::jsonb) ? 'breakoutVolumeBackfill')
      `);
      written += 1;
    } catch (error40) {
      logger.warn(
        { error: error40, id: row.id, symbol: row.symbol },
        "Stealth breakout volume backfill failed for position"
      );
    }
  }
  return written;
}

// src/lib/range-deviation-followup.ts
init_src();
init_drizzle_orm();
init_bingx();
init_logger2();
var RANGE_DEVIATION_FOLLOWUP_INTERVAL_MS = 15 * 60 * 1e3;
var M154 = 15 * 60 * 1e3;
var TFS = ["tf1d", "tf4h", "tf1h"];
async function runRangeDeviationFollowup() {
  if (process.env.NODE_ENV !== "production") return 0;
  const result = await db.execute(sql`
    SELECT id, symbol, decision_metrics->'rangeDeviation' AS ctx
      FROM tracked_signals
     WHERE status::text IN ('active', 'in_run')
       AND decision_metrics ? 'rangeDeviation'
     ORDER BY id
  `);
  let updated = 0;
  for (const row of result.rows) {
    try {
      const fireAt = Number(row.ctx?.capturedAt);
      if (!Number.isFinite(fireAt)) continue;
      const frames = TFS.filter(
        (tf) => row.ctx[tf]?.hasRange && Number(row.ctx[tf]?.lower) > 0
      );
      const now2 = Date.now();
      const klines = await withAggregatedKlineVolume(
        row.symbol,
        "15m",
        await getKlines(
          row.symbol,
          "15m",
          Math.min(1e3, Math.ceil((now2 - fireAt) / M154) + 4)
        )
      );
      const candles = klines.map((k) => ({
        time: Number(k.time),
        open: Number(k.open),
        high: Number(k.high),
        low: Number(k.low),
        close: Number(k.close),
        volume: Number(k.volume)
      }));
      const out = {};
      for (const tf of frames) {
        const lower = Number(row.ctx[tf].lower);
        const { events, belowUnreclaimed } = findDeviations(
          candles,
          lower,
          now2,
          fireAt
        );
        out[tf] = { lower, events, belowUnreclaimed };
      }
      const payload = {
        candleReaction: findCandleReaction(candles, now2, fireAt),
        source: "post_fire_15m",
        since: fireAt,
        updatedAt: now2,
        ...out
      };
      await db.execute(sql`
        UPDATE tracked_signals
           SET decision_metrics = COALESCE(decision_metrics, '{}'::jsonb) ||
               jsonb_build_object('rangeDeviationAfter', ${JSON.stringify(payload)}::jsonb)
         WHERE id = ${row.id}
           AND status::text IN ('active', 'in_run')
      `);
      updated += 1;
    } catch (error40) {
      logger.warn(
        { error: error40, id: row.id, symbol: row.symbol },
        "Range deviation follow-up failed for position"
      );
    }
  }
  return updated;
}
var running3 = false;
function startRangeDeviationFollowup() {
  const tick = () => {
    if (running3) return;
    running3 = true;
    runRangeDeviationFollowup().then(
      (count2) => logger.info({ count: count2 }, "Range deviation follow-up updated")
    ).catch((err) => logger.warn({ err }, "Range deviation follow-up failed")).finally(() => {
      running3 = false;
    });
  };
  setTimeout(tick, 5 * 60 * 1e3).unref();
  setInterval(tick, RANGE_DEVIATION_FOLLOWUP_INTERVAL_MS).unref();
}

