async function ensureScannerRecoverySchema() {
  await db.transaction(async (tx) => {
    await tx.execute(
      sql`SELECT pg_advisory_xact_lock(hashtext('scanner_recovery_schema'))`
    );
    await tx.execute(
      sql`ALTER TABLE settings ADD COLUMN IF NOT EXISTS scanner_last_scan_at TIMESTAMP`
    );
    await tx.execute(
      sql`ALTER TABLE settings ADD COLUMN IF NOT EXISTS scanner_scan_started_at TIMESTAMP`
    );
    await tx.execute(
      sql`ALTER TABLE settings ADD COLUMN IF NOT EXISTS scanner_last_scan_duration_ms INTEGER`
    );
    await tx.execute(sql`
      UPDATE settings
      SET scanner_last_scan_duration_ms = GREATEST(
        0,
        (EXTRACT(EPOCH FROM (scanner_last_scan_at - scanner_scan_started_at)) * 1000)::INTEGER
      )
      WHERE scanner_last_scan_duration_ms IS NULL
        AND scanner_last_scan_at IS NOT NULL
        AND scanner_scan_started_at IS NOT NULL
        AND scanner_last_scan_at >= scanner_scan_started_at
    `);
    await tx.execute(
      sql`ALTER TABLE settings ADD COLUMN IF NOT EXISTS scanner_failure_at TIMESTAMP`
    );
    await tx.execute(
      sql`ALTER TABLE settings ADD COLUMN IF NOT EXISTS scanner_failure_reason TEXT`
    );
    await tx.execute(
      sql`ALTER TABLE settings ADD COLUMN IF NOT EXISTS scanner_failure_diagnostics_json TEXT`
    );
    await tx.execute(
      sql`ALTER TABLE settings ADD COLUMN IF NOT EXISTS scanner_lease_expected_expiry_at TIMESTAMP`
    );
    await tx.execute(
      sql`ALTER TABLE settings ADD COLUMN IF NOT EXISTS scanner_last_failure_at TIMESTAMP`
    );
    await tx.execute(
      sql`ALTER TABLE settings ADD COLUMN IF NOT EXISTS scanner_last_failure_reason TEXT`
    );
    await tx.execute(
      sql`ALTER TABLE settings ADD COLUMN IF NOT EXISTS scanner_retry_at TIMESTAMP`
    );
  });
}
